/* A transparent traditional worksheet, not a clinical fetal-sex determination. */
(function(root){'use strict';
const IDS=['Su','Mo','Ma','Me','Ju','Ve','Sa','Ra','Ke'],names={Su:['Sun','रवी'],Mo:['Moon','चंद्र'],Ma:['Mars','मंगळ'],Me:['Mercury','बुध'],Ju:['Jupiter','गुरु'],Ve:['Venus','शुक्र'],Sa:['Saturn','शनि'],Ra:['Rahu','राहू'],Ke:['Ketu','केतू']};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;', '"':'&quot;'}[c]));
const parity=p=>Number.isInteger(p?.signIndex)&&p.signIndex>=0&&p.signIndex<12?(p.signIndex%2===0?'male':'female'):null;
const nature=id=>!IDS.includes(id)?null:['Su','Ma','Ju'].includes(id)?'male':['Mo','Ve','Ra'].includes(id)?'female':'neutral';
function build({model,rp,judgmentPlanets,number,prashnaMD}){
 const natal=new Map((model?.planets||[]).map(p=>[p.id,p])),judgment=new Map((judgmentPlanets||[]).map(p=>[p.id,p])),cusp=model?.houses?.find(h=>h.id===5);
 const chain=(id,points)=>{const p=points.get(id),sub=points.get(p?.sl),star=points.get(sub?.stl);return {id,sub:sub?.id||null,star:star?.id||null,sign:star?.signIndex??null,result:parity(star)};};
 const csl=natal.get(cusp?.sl),cslStar=natal.get(csl?.stl),ssl=natal.get(cusp?.ssl),sslStar=natal.get(ssl?.stl);
 const rpIds=[rp?.dayLord,rp?.points?.[0]?.sgl,rp?.points?.[0]?.stl,rp?.points?.[0]?.sl,rp?.points?.[1]?.sgl,rp?.points?.[1]?.stl,rp?.points?.[1]?.sl];
 const rpRows=rpIds.map(id=>chain(id,judgment)),count=rows=>({male:rows.filter(r=>r.result==='male').length,female:rows.filter(r=>r.result==='female').length});
 const majority=rows=>{const n=count(rows);return n.male===n.female?null:n.male>n.female?'male':'female';},n=count(rpRows),tie=chain(rp?.points?.[1]?.sl,judgment);
 const joint=[cusp?.sgl,cusp?.stl,cusp?.sl].map(id=>{const p=natal.get(id),st=natal.get(p?.stl),sl=natal.get(p?.sl);return {id,nature:nature(id),star:st?.id,starNature:nature(st?.id),starSign:st?.signIndex,sub:sl?.id,subNature:nature(sl?.id),subSign:sl?.signIndex};});
 const md=natal.get(prashnaMD),mdRows=[md,natal.get(md?.stl),natal.get(md?.sl)].map(p=>({id:p?.id,sign:p?.signIndex,result:parity(p)}));
 const validNumber=Number.isInteger(number)&&number>=1&&number<=249;
 const steps=[{result:parity(cslStar),lord:csl?.id,star:cslStar?.id,sign:cslStar?.signIndex},{result:majority(rpRows)||tie.result,counts:n,tie:n.male===n.female},{result:parity(sslStar),lord:ssl?.id,star:sslStar?.id,sign:sslStar?.signIndex},{result:validNumber?(number%12%2?'male':'female'):null,remainder:validNumber?number%12:null},{result:null},{result:prashnaMD?majority(mdRows):null}];
 return {ready:Boolean(model?.ready&&cusp),cusp,rpRows,joint,mdRows,steps,rpCount:n,number:validNumber?number:null,utc:rp?.utc,location:rp?.location,hasPrashnaMD:Boolean(prashnaMD),policy:'Step 5 has no supplied aggregation rule; it remains a joint-ruler comparison, not an invented vote. No overall fetal-sex determination.'};
}
function render(d,lang='english',info={}){
 const mr=lang==='marathi',say=(en,ma)=>mr?ma:en,p=id=>names[id]?.[mr?1:0]||'—',sex=s=>s?say({male:'Male',female:'Female',neutral:'Neutral'}[s],{male:'पुरुष',female:'स्त्री',neutral:'नपुंसक'}[s]):'—',sign=n=>Number.isInteger(n)?String(n+1)+' · '+sex(n%2===0?'male':'female'):'—';
 const table=(heads,rows)=>'<table><thead><tr>'+heads.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
 const section=(n,title,body)=>'<section><h2>'+n+'. '+title+'</h2>'+body+'</section>',rpLabels=mr?['वार स्वामी','लग्न राशीस्वामी','लग्न नक्षत्रस्वामी','लग्न उपस्वामी','चंद्र राशीस्वामी','चंद्र नक्षत्रस्वामी','चंद्र उपस्वामी']:['Day lord','Asc sign lord','Asc star lord','Asc sub lord','Moon sign lord','Moon star lord','Moon sub lord'];
 const dms=(v,lon=false)=>{if(!Number.isFinite(v))return '—';let s=Math.round(Math.abs(v)*3600);return Math.floor(s/3600)+'°'+Math.floor(s%3600/60)+'′'+s%60+'″ '+(lon?(v<0?'W':'E'):(v<0?'S':'N'));};
 return '<article class="cg-page" lang="'+(mr?'mr':'en')+'"><header><h1>'+say('Child Gender · Traditional KP Worksheet','बाललिंग · पारंपरिक केपी परीक्षण पत्रक')+'</h1><p>'+esc(info.name||'')+' · '+esc(info.chart||'')+'</p><p>'+say('Judgment','निर्णय वेळ')+': '+esc(info.time||d.utc||'—')+' · '+esc(d.location?.place||'')+' · '+dms(d.location?.latitude)+' / '+dms(d.location?.longitude,true)+'</p></header><p class="cg-notice">'+say('Traditional astrology reference only. This sheet does not reliably determine fetal sex or replace medical care. Blank cells mean unavailable data; conflicting checks remain unresolved.','हे केवळ पारंपरिक ज्योतिषीय संदर्भपत्रक आहे. यावरून गर्भाचे लिंग विश्वसनीयपणे ठरत नाही व वैद्यकीय सल्ल्याची जागा घेत नाही. रिकाम्या नोंदी म्हणजे माहिती अनुपलब्ध; परस्परविरोधी संकेत अनिर्णीत आहेत.')+'</p>'+section(1,say('Fifth cusp sub lord → its star lord → sign','पंचम भाव उपस्वामी → त्याचा नक्षत्रस्वामी → राशी'),'<p>'+p(d.steps[0].lord)+' → '+p(d.steps[0].star)+' → '+sign(d.steps[0].sign)+' · '+sex(d.steps[0].result)+'</p>')+section(2,say('Seven ruling-planet posts at judgment time','निर्णयवेळचे सात शासक ग्रह पद'),table([say('Post','पद'),say('Planet','ग्रह'),say('Its sub','त्याचा उपस्वामी'),say('Star of sub','उपाचा नक्षत्रस्वामी'),say('Sign / indication','राशी / संकेत')],d.rpRows.map((r,i)=>[rpLabels[i],p(r.id),p(r.sub),p(r.star),sign(r.sign)]))+'<p>'+say('Male / female counts','पुरुष / स्त्री संख्या')+': '+d.rpCount.male+' / '+d.rpCount.female+' · '+sex(d.steps[1].result)+(d.steps[1].tie?' · '+say('Tie: Moon-sub chain checked','समान संख्या: चंद्र उपस्वामी साखळी तपासली'):'')+'</p>')+section(3,say('Fifth cusp sub-sub lord → its star lord','पंचम भाव उप-उपस्वामी → त्याचा नक्षत्रस्वामी'),'<p>'+p(d.steps[2].lord)+' → '+p(d.steps[2].star)+' → '+sign(d.steps[2].sign)+'</p>')+section(4,say('Horary number ÷ 12','प्रश्नांक ÷ १२'),'<p>'+say('Number','प्रश्नांक')+': '+(d.number??'—')+' · '+say('Remainder','बाकी')+': '+(d.steps[3].remainder??'—')+' · '+sex(d.steps[3].result)+'</p>')+section(5,say('Fifth cusp joint rulers · V. S. N. Murthy method (as supplied)','पंचम भाव संयुक्त स्वामी · व्ही. एस. एन. मूर्ती पद्धत (दिलेल्या नोंदीनुसार)'),table([say('Planet / nature','ग्रह / प्रकृती'),say('Star / nature','नक्षत्रस्वामी / प्रकृती'),say('Star sign','नक्षत्रस्वामीची राशी'),say('Sub / nature','उपस्वामी / प्रकृती'),say('Sub sign','उपस्वामीची राशी')],d.joint.map(r=>[p(r.id)+' / '+sex(r.nature),p(r.star)+' / '+sex(r.starNature),sign(r.starSign),p(r.sub)+' / '+sex(r.subNature),sign(r.subSign)]))+'<p>'+say('No aggregation rule was supplied for this method.','या पद्धतीतील एकत्रित निकालाचा नियम दिलेला नाही.')+'</p>')+section(6,say('Present Prashna mahadasha','सध्याची प्रश्न महादशा'),d.hasPrashnaMD?table([say('Lord','स्वामी'),say('Sign / indication','राशी / संकेत')],d.mdRows.map(r=>[p(r.id),sign(r.sign)])):'<p>'+say('Requires an active Prashna chart; natal dasha is not substituted.','सक्रिय प्रश्नकुंडली आवश्यक; जन्मदशा वापरलेली नाही.')+'</p>')+section(7,say('Comparison / opinion / actual outcome','तुलना / माझे मत / प्रत्यक्ष निष्कर्ष'),'<p>'+d.steps.map((s,i)=>(i+1)+': '+sex(s.result)).join(' · ')+'</p><p>'+say('Conclusion: compare all checks; no automatic medical conclusion.','निष्कर्ष: सर्व संकेतांची तुलना करावी; स्वयंचलित वैद्यकीय निष्कर्ष नाही.')+'</p><label>'+say('My opinion','माझे मत')+': <span contenteditable="true" role="textbox">'+esc(info.opinion||'____________________________')+'</span></label><p>'+say('Actual outcome / correct or incorrect','प्रत्यक्ष निष्कर्ष / बरोबर किंवा चूक')+': <span contenteditable="true" role="textbox">____________________________</span></p>')+'</article>';
}
function open(){
 const model=root.currentKPModel;if(!model?.ready)return false;
 const lang=root.KPPreferences?.get?.().language||'english',mr=lang==='marathi';if(!['english','marathi','bilingual'].includes(lang))return false;
 const w=root.open('','_blank');if(!w)return false;
 try{const date=new Date(),location=root.KPDefaultLocation.get(),rp=root.KPLiveRuling.calculate(date,location),positions=root.KPEphemeris.positions(date),judgmentPlanets=IDS.map(id=>({id,...root.KPDisplay.longitudeDetails(positions[id]*3600)})),horary=root.document.getElementById('chart-kind')?.value==='horary'||root.document.getElementById('instant-prashna')?.value==='1',prashnaMD=horary?root.KPDashaFal.current(model,date)?.periods?.[0]?.id:null;
 const d=build({model,rp,judgmentPlanets,number:horary&&root.document.getElementById('horary-system')?.value!=='2193'?Number(root.document.getElementById('horary-number')?.value):null,prashnaMD});
 const css='@page{size:A4 portrait;margin:10mm}*{box-sizing:border-box}body{margin:0;background:#edf2f7;color:#18334d;font:10px/1.3 Arial,"Nirmala UI",Mangal,sans-serif}.cg-page{width:190mm;max-width:100%;min-height:0;margin:12px auto;padding:5mm;background:white}h1{font-size:17px;margin:0 0 3px}h2{font-size:11px;margin:5px 0 2px;color:#204f76}p{margin:3px 0}section{break-inside:avoid}table{border-collapse:collapse;width:100%;table-layout:fixed}th,td{border:1px solid #9eafbf;padding:2px 4px;overflow-wrap:anywhere}th{background:#eaf1f8;text-align:left}.cg-notice{font-size:9px;border-left:3px solid #477da5;padding:4px;background:#f1f6fb}.cg-actions{padding:10px;position:sticky;top:0;background:white}button{padding:7px 15px;margin-right:6px}[contenteditable]{display:inline-block;min-width:100px}@media print{body{background:white}.cg-page{width:190mm;max-width:none;margin:0;padding:0;font-size:9px}.cg-actions{display:none}h1{font-size:15px}h2{font-size:10px}th,td{padding:2px 3px}}';
 w.document.open();w.document.write('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+ (mr?'संतती परीक्षण पत्रक':'Child Gender Worksheet')+'</title><style>'+css+'</style></head><body><nav class="cg-actions"><button onclick="print()">'+(mr?'छापा / पीडीएफ जतन करा':'Print / Save PDF')+'</button><button onclick="close()">'+(mr?'बंद करा':'Close')+'</button></nav>'+render(d,lang,{name:root.document.getElementById('name')?.value,chart:horary?(mr?'प्रश्नकुंडली':'Prashna chart'):(mr?'जन्मकुंडली':'Natal chart'),time:rp.local+' (UTC '+location.timezone+')'})+'</body></html>');w.document.close();return true;
 }catch(e){w.document.open();w.document.write('<p>'+esc(e.message)+'</p>');w.document.close();return false;}
}
root.KPChildGenderSheet=Object.freeze({build,render,open});if(typeof module!=='undefined'&&module.exports)module.exports=root.KPChildGenderSheet;
})(typeof window==='undefined'?globalThis:window);
